if (URI.SCHEMES["http"]) {

	//module("HTTP");

	test("HTTP Equals", function () {
		//test from RFC 2616
		strictEqual(URI.equal("http://example.invalid:80/~smith/home.html", "http://example.invalid/~smith/home.html"), true);
		strictEqual(URI.equal("http://example.invalid/%7Esmith/home.html", "http://example.invalid/~smith/home.html"), true);
		strictEqual(URI.equal("http://example.invalid:/%7esmith/home.html", "http://example.invalid/~smith/home.html"), true);
		strictEqual(URI.equal("HTTP://example.invalid", "http://example.invalid/"), true);
		//test from RFC 3986
		strictEqual(URI.equal("http://example.invalid:/", "http://example.invalid:80/"), true);
	});

}

