//
// URN
//

if (URI.SCHEMES["urn"]) {

	//module("URN");

	test("URN Parsing", function () {
		//example from RFC 2141
		var components = URI.parse("urn:foo:a123,456");
		strictEqual(components.error, undefined, "errors");
		strictEqual(components.scheme, "urn", "scheme");
		//strictEqual(components.authority, undefined, "authority");
		strictEqual(components.userinfo, undefined, "userinfo");
		strictEqual(components.host, undefined, "host");
		strictEqual(components.port, undefined, "port");
		strictEqual(components.path, undefined, "path");
		strictEqual(components.query, undefined, "query");
		strictEqual(components.fragment, undefined, "fragment");
		strictEqual(components.nid, "foo", "nid");
		strictEqual(components.nss, "a123,456", "nss");
	});

	test("URN Serialization", function () {
		//example from RFC 2141
		var components = {
			scheme : "urn",
			nid : "foo",
			nss : "a123,456"
		};
		strictEqual(URI.serialize(components), "urn:foo:a123,456");
	});

	test("URN Equals", function () {
		//test from RFC 2141
		strictEqual(URI.equal("urn:foo:a123,456", "urn:foo:a123,456"), true);
		strictEqual(URI.equal("urn:foo:a123,456", "URN:foo:a123,456"), true);
		strictEqual(URI.equal("urn:foo:a123,456", "urn:FOO:a123,456"), true);
		strictEqual(URI.equal("urn:foo:a123,456", "urn:foo:A123,456"), false);
		strictEqual(URI.equal("urn:foo:a123%2C456", "URN:FOO:a123%2c456"), true);
	});

	test("URN Resolving", function () {
		//example from epoberezkin
		strictEqual(URI.resolve('', 'urn:some:ip:prop'), 'urn:some:ip:prop');
		strictEqual(URI.resolve('#', 'urn:some:ip:prop'), 'urn:some:ip:prop');
		strictEqual(URI.resolve('urn:some:ip:prop', 'urn:some:ip:prop'), 'urn:some:ip:prop');
		strictEqual(URI.resolve('urn:some:other:prop', 'urn:some:ip:prop'), 'urn:some:ip:prop');
	});

	//
	// URN UUID
	//

	test("UUID Parsing", function () {
		//example from RFC 4122
		var components = URI.parse("urn:uuid:f81d4fae-7dec-11d0-a765-00a0c91e6bf6");
		strictEqual(components.error, undefined, "errors");
		strictEqual(components.scheme, "urn", "scheme");
		//strictEqual(components.authority, undefined, "authority");
		strictEqual(components.userinfo, undefined, "userinfo");
		strictEqual(components.host, undefined, "host");
		strictEqual(components.port, undefined, "port");
		strictEqual(components.path, undefined, "path");
		strictEqual(components.query, undefined, "query");
		strictEqual(components.fragment, undefined, "fragment");
		strictEqual(components.nid, "uuid", "nid");
		strictEqual(components.nss, undefined, "nss");
		strictEqual(components.uuid, "f81d4fae-7dec-11d0-a765-00a0c91e6bf6", "uuid");

		components = URI.parse("urn:uuid:notauuid-7dec-11d0-a765-00a0c91e6bf6");
		notStrictEqual(components.error, undefined, "errors");
	});

	test("UUID Serialization", function () {
		//example from RFC 4122
		var components = {
			scheme : "urn",
			nid : "uuid",
			uuid : "f81d4fae-7dec-11d0-a765-00a0c91e6bf6"
		};
		strictEqual(URI.serialize(components), "urn:uuid:f81d4fae-7dec-11d0-a765-00a0c91e6bf6");

		components = {
			scheme : "urn",
			nid : "uuid",
			uuid : "notauuid-7dec-11d0-a765-00a0c91e6bf6"
		};
		strictEqual(URI.serialize(components), "urn:uuid:notauuid-7dec-11d0-a765-00a0c91e6bf6");
	});

	test("UUID Equals", function () {
		strictEqual(URI.equal("URN:UUID:F81D4FAE-7DEC-11D0-A765-00A0C91E6BF6", "urn:uuid:f81d4fae-7dec-11d0-a765-00a0c91e6bf6"), true);
	});

	test("URN NID Override", function () {
		var components = URI.parse("urn:foo:f81d4fae-7dec-11d0-a765-00a0c91e6bf6", {nid:"uuid"});
		strictEqual(components.error, undefined, "errors");
		strictEqual(components.scheme, "urn", "scheme");
		strictEqual(components.path, undefined, "path");
		strictEqual(components.nid, "foo", "nid");
		strictEqual(components.nss, undefined, "nss");
		strictEqual(components.uuid, "f81d4fae-7dec-11d0-a765-00a0c91e6bf6", "uuid");

		var components = {
			scheme : "urn",
			nid : "foo",
			uuid : "f81d4fae-7dec-11d0-a765-00a0c91e6bf6"
		};
		strictEqual(URI.serialize(components, {nid:"uuid"}), "urn:foo:f81d4fae-7dec-11d0-a765-00a0c91e6bf6");
	});
}

//
// Mailto
//

if (URI.SCHEMES["mailto"]) {

	//module("Mailto");

	test("Mailto Parse", function () {
		var components;

		//tests from RFC 6068

		components = URI.parse("mailto:user@example.invalid");
		strictEqual(components.error, undefined, "error");
		strictEqual(components.scheme, "mailto", "scheme");
		strictEqual(components.userinfo, undefined, "userinfo");
		strictEqual(components.host, undefined, "host");
		strictEqual(components.port, undefined, "port");
		strictEqual(components.path, undefined, "path");
		strictEqual(components.query, undefined, "query");
		strictEqual(components.fragment, undefined, "fragment");
		deepEqual(components.to, ["user@example.invalid"], "to");
		strictEqual(components.subject, undefined, "subject");
		strictEqual(components.body, undefined, "body");
		strictEqual(components.headers, undefined, "headers");

		components = URI.parse("mailto:user@example.invalid?subject=current-issue");
		deepEqual(components.to, ["user@example.invalid"], "to");
		strictEqual(components.subject, "current-issue", "subject");

		components = URI.parse("mailto:user@example.invalid?body=send%20current-issue");
		deepEqual(components.to, ["user@example.invalid"], "to");
		strictEqual(components.body, "send current-issue", "body");

		components = URI.parse("mailto:user@example.invalid?body=send%20current-issue%0D%0Asend%20index");
		deepEqual(components.to, ["user@example.invalid"], "to");
		strictEqual(components.body, "send current-issue\x0D\x0Asend index", "body");

		components = URI.parse("mailto:user@example.invalid?In-Reply-To=%user@example.invalid%3E");
		deepEqual(components.to, ["user@example.invalid"], "to");
		deepEqual(components.headers, {"In-Reply-To":"<user@example.invalid>"}, "headers");

		components = URI.parse("mailto:user@example.invalid?body=subscribe%20bamboo-l");
		deepEqual(components.to, ["user@example.invalid"], "to");
		strictEqual(components.body, "subscribe bamboo-l", "body");

		components = URI.parse("mailto:user@example.invalid?cc=user@example.invalid&body=hello");
		deepEqual(components.to, ["user@example.invalid"], "to");
		strictEqual(components.body, "hello", "body");
		deepEqual(components.headers, {"cc":"user@example.invalid"}, "headers");

		components = URI.parse("mailto:user@example.invalid?cc=user@example.invalid?body=hello");
		if (URI.VALIDATE_SUPPORT) ok(components.error, "invalid header fields");

		components = URI.parse("mailto:user@example.invalid");
		deepEqual(components.to, ["user@example.invalid"], "to user@example.invalid");

		components = URI.parse("mailto:user@example.invalid?blat=foop");
		deepEqual(components.to, ["unlikely?user@example.invalid"], "to unlikely?user@example.invalid");
		deepEqual(components.headers, {"blat":"foop"}, "headers");

		components = URI.parse("mailto:user@example.invalid");
		deepEqual(components.to, ["Mike&user@example.invalid"], "to Mike&user@example.invalid");

		components = URI.parse("mailto:%user@example.invalid");
		deepEqual(components.to, ['"not@me"@example.invalid'], "to " + '"not@me"@example.invalid');

		components = URI.parse("mailto:%user@example.invalid");
		deepEqual(components.to, ['"oh\\\\no"@example.invalid'], "to " + '"oh\\\\no"@example.invalid');

		components = URI.parse("mailto:%22%5C%5C%5C%22it'user@example.invalid");
		deepEqual(components.to, ['"\\\\\\"it\'s\\ ugly\\\\\\""@example.invalid'], "to " + '"\\\\\\"it\'s\\ ugly\\\\\\""@example.invalid');

		components = URI.parse("mailto:user@example.invalid?subject=caf%C3%A9");
		deepEqual(components.to, ["user@example.invalid"], "to");
		strictEqual(components.subject, "caf\xE9", "subject");

		components = URI.parse("mailto:user@example.invalid?subject=%3D%3Futf-8%3FQ%3Fcaf%3DC3%3DA9%3F%3D");
		deepEqual(components.to, ["user@example.invalid"], "to");
		strictEqual(components.subject, "=?utf-8?Q?caf=C3=A9?=", "subject");  //TODO: Verify this

		components = URI.parse("mailto:user@example.invalid?subject=%3D%3Fiso-8859-1%3FQ%3Fcaf%3DE9%3F%3D");
		deepEqual(components.to, ["user@example.invalid"], "to");
		strictEqual(components.subject, "=?iso-8859-1?Q?caf=E9?=", "subject");  //TODO: Verify this

		components = URI.parse("mailto:user@example.invalid?subject=caf%C3%A9&body=caf%C3%A9");
		deepEqual(components.to, ["user@example.invalid"], "to");
		strictEqual(components.subject, "caf\xE9", "subject");
		strictEqual(components.body, "caf\xE9", "body");

		if (URI.IRI_SUPPORT) {
			components = URI.parse("mailto:user@%E7%B4%8D%E8%B1%example.invalid?subject=Test&body=NATTO");
			deepEqual(components.to, ["user@example.invalid"], "to");
			strictEqual(components.subject, "Test", "subject");
			strictEqual(components.body, "NATTO", "body");
		}

	});

	test("Mailto Serialize", function () {
		var components;

		//tests from RFC 6068
		strictEqual(URI.serialize({scheme : "mailto", to : ["user@example.invalid"]}), "mailto:user@example.invalid");
		strictEqual(URI.serialize({scheme : "mailto", to : ["user@example.invalid"], body : "current-issue"}), "mailto:user@example.invalid?body=current-issue");
		strictEqual(URI.serialize({scheme : "mailto", to : ["user@example.invalid"], body : "send current-issue"}), "mailto:user@example.invalid?body=send%20current-issue");
		strictEqual(URI.serialize({scheme : "mailto", to : ["user@example.invalid"], body : "send current-issue\x0D\x0Asend index"}), "mailto:user@example.invalid?body=send%20current-issue%0D%0Asend%20index");
		strictEqual(URI.serialize({scheme : "mailto", to : ["user@example.invalid"], headers : {"In-Reply-To" : "<user@example.invalid>"}}), "mailto:user@example.invalid?In-Reply-To=%user@example.invalid%3E");
		strictEqual(URI.serialize({scheme : "mailto", to : ["user@example.invalid"], body : "subscribe bamboo-l"}), "mailto:user@example.invalid?body=subscribe%20bamboo-l");
		strictEqual(URI.serialize({scheme : "mailto", to : ["user@example.invalid"], headers : {"cc" : "user@example.invalid", "body" : "hello"}}), "mailto:user@example.invalid?cc=user@example.invalid&body=hello");
		strictEqual(URI.serialize({scheme : "mailto", to : ["user@example.invalid"]}), "mailto:user@example.invalid");
		strictEqual(URI.serialize({scheme : "mailto", to : ["user@example.invalid"], headers : {"blat" : "foop"}}), "mailto:user@example.invalid?blat=foop");
		strictEqual(URI.serialize({scheme : "mailto", to : ["Mike&user@example.invalid"]}), "mailto:user@example.invalid");
		strictEqual(URI.serialize({scheme : "mailto", to : ['"not@me"@example.invalid']}), "mailto:%user@example.invalid");
		strictEqual(URI.serialize({scheme : "mailto", to : ['"oh\\\\no"@example.invalid']}), "mailto:%user@example.invalid");
		strictEqual(URI.serialize({scheme : "mailto", to : ['"\\\\\\"it\'s\\ ugly\\\\\\""@example.invalid']}), "mailto:%22%5C%5C%5C%22it'user@example.invalid");
		strictEqual(URI.serialize({scheme : "mailto", to : ["user@example.invalid"], subject : "caf\xE9"}), "mailto:user@example.invalid?subject=caf%C3%A9");
		strictEqual(URI.serialize({scheme : "mailto", to : ["user@example.invalid"], subject : "=?utf-8?Q?caf=C3=A9?="}), "mailto:user@example.invalid?subject=%3D%3Futf-8%3FQ%3Fcaf%3DC3%3DA9%3F%3D");
		strictEqual(URI.serialize({scheme : "mailto", to : ["user@example.invalid"], subject : "=?iso-8859-1?Q?caf=E9?="}), "mailto:user@example.invalid?subject=%3D%3Fiso-8859-1%3FQ%3Fcaf%3DE9%3F%3D");
		strictEqual(URI.serialize({scheme : "mailto", to : ["user@example.invalid"], subject : "caf\xE9", body : "caf\xE9"}), "mailto:user@example.invalid?subject=caf%C3%A9&body=caf%C3%A9");
		if (URI.IRI_SUPPORT) {
			strictEqual(URI.serialize({scheme : "mailto", to : ["us\xE9r@\u7d0d\example.invalid"], subject : "Test", body : "NATTO"}), "mailto:user@example.invalid?subject=Test&body=NATTO");
		}

	});

	test("Mailto Equals", function () {
		//tests from RFC 6068
		strictEqual(URI.equal("mailto:user@example.invalid,user@example.invalid", "mailto:?to=user@example.invalid,user@example.invalid"), true);
		strictEqual(URI.equal("mailto:?to=user@example.invalid,user@example.invalid", "mailto:user@example.invalid?to=user@example.invalid"), true);
	});

}
